-- DEMONSTRATION DATA ONLY. Stalls, prices and stock photos are illustrative.
-- Do not apply to production without replacing and verifying the listings.

-- Future demonstration slots in Asia/Manila, refreshed each time the seed is applied.
select s.id, ((now() at time zone 'Asia/Manila')::date + d + t) at time zone 'Asia/Manila', ((now() at time zone 'Asia/Manila')::date + d + t + interval '30 minutes') at time zone 'Asia/Manila',20
from public.stalls s cross join generate_series(0,6) d cross join (values (time '11:00'),(time '11:30'),(time '12:00'),(time '12:30'),(time '13:00'),(time '16:00')) slots(t)
where s.is_demo and ((now() at time zone 'Asia/Manila')::date + d + t) at time zone 'Asia/Manila'>now()
on conflict(stall_id,start_time) do nothing;
